<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();srnu_auth_require_admin();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!srnu_auth_check_csrf($_POST['csrf']??null))$err='Formulario expirado.';
 else{
  $accion=(string)($_POST['accion']??'');
  if($accion==='crear'){
   $nombre=trim((string)($_POST['nombre']??''));$usuario=trim((string)($_POST['usuario']??''));$rol=in_array($_POST['rol']??'', ['admin','taller'],true)?$_POST['rol']:'taller';$p=(string)($_POST['password']??'');
   if(strlen($nombre)<3||!preg_match('/^[A-Za-z0-9._-]{3,40}$/',$usuario)||strlen($p)<10)$err='Revisa nombre, usuario y contraseña (mínimo 10 caracteres).';
   else{try{$s=$pdo->prepare('INSERT INTO usuarios(nombre,usuario,password_hash,rol,activo) VALUES(?,?,?,?,1)');$s->execute([$nombre,$usuario,password_hash($p,PASSWORD_DEFAULT),$rol]);$msg='Usuario creado.';}catch(Throwable $e){$err='No se pudo crear. El usuario puede estar repetido.';}}
  } elseif($accion==='estado'){
   $id=(int)($_POST['id']??0);$activo=!empty($_POST['activo'])?1:0;$me=(int)(srnu_auth_user()['id']??0);if($id===$me && !$activo)$err='No puedes desactivar tu propia sesión.';else{if(!$activo){$q=$pdo->prepare("SELECT COUNT(*) FROM usuarios WHERE id=? AND rol='admin' AND activo=1");$q->execute([$id]);$esAdmin=(int)$q->fetchColumn()===1;$admins=(int)$pdo->query("SELECT COUNT(*) FROM usuarios WHERE rol='admin' AND activo=1")->fetchColumn();if($esAdmin&&$admins<=1){$err='Debe quedar al menos un administrador activo.';}else{$pdo->prepare('UPDATE usuarios SET activo=? WHERE id=?')->execute([$activo,$id]);$msg='Estado actualizado.';}}else{$pdo->prepare('UPDATE usuarios SET activo=1 WHERE id=?')->execute([$id]);$msg='Estado actualizado.';}}
  } elseif($accion==='password'){
   $id=(int)($_POST['id']??0);$p=(string)($_POST['password']??'');if(strlen($p)<10)$err='La nueva contraseña debe tener al menos 10 caracteres.';else{$pdo->prepare('UPDATE usuarios SET password_hash=? WHERE id=?')->execute([password_hash($p,PASSWORD_DEFAULT),$id]);$msg='Contraseña actualizada.';}
  } elseif($accion==='rol'){
   $id=(int)($_POST['id']??0);$rol=in_array($_POST['rol']??'', ['admin','taller'],true)?$_POST['rol']:'taller';$q=$pdo->prepare("SELECT rol,activo FROM usuarios WHERE id=?");$q->execute([$id]);$actual=$q->fetch();$admins=(int)$pdo->query("SELECT COUNT(*) FROM usuarios WHERE rol='admin' AND activo=1")->fetchColumn();if($actual&&$actual['rol']==='admin'&&(int)$actual['activo']===1&&$rol!=='admin'&&$admins<=1){$err='Debe quedar al menos un administrador activo.';}else{$pdo->prepare('UPDATE usuarios SET rol=? WHERE id=?')->execute([$rol,$id]);$msg='Rol actualizado.';}
  }
 }
}
$rows=$pdo->query('SELECT id,nombre,usuario,rol,activo,ultimo_acceso,created_at FROM usuarios ORDER BY activo DESC,nombre')->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuarios · SRNU</title><link rel="icon" href="favicon.png"><?=srnu_ui_head()?></head><body><?php srnu_appbar('usuarios');?><main class="w"><div class="srnu-page-heading"><div><h1>Usuarios y acceso</h1><p>Cuentas internas para entrar al ERP cuando esté disponible por LAN o internet.</p></div></div><?php if($msg):?><div class="srnu-ok"><?=eh($msg)?></div><?php endif;?><?php if($err):?><div class="srnu-security-note"><?=eh($err)?></div><?php endif;?><section class="panel" style="padding:18px;margin-top:16px"><h3>Agregar usuario</h3><form method="post" class="erp-form cols-4"><input type="hidden" name="csrf" value="<?=eh(srnu_auth_csrf())?>"><input type="hidden" name="accion" value="crear"><input name="nombre" required placeholder="Nombre completo"><input name="usuario" required placeholder="Usuario"><select name="rol"><option value="taller">Taller</option><option value="admin">Administrador</option></select><input type="password" name="password" required minlength="10" placeholder="Contraseña · mínimo 10"><button class="btn blue">Crear usuario</button></form><p class="muted">Administrador: acceso total. Taller: operación, cotizaciones, clientes, agenda e inventario; se restringen finanzas, costos, compras, proveedores, reportes, IA/configuración y usuarios.</p></section><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Último acceso</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=eh($r['nombre'])?></b></td><td><?=eh($r['usuario'])?></td><td><form method="post" class="toolbar"><input type="hidden" name="csrf" value="<?=eh(srnu_auth_csrf())?>"><input type="hidden" name="accion" value="rol"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="rol"><option value="admin" <?=$r['rol']==='admin'?'selected':''?>>Administrador</option><option value="taller" <?=$r['rol']==='taller'?'selected':''?>>Taller</option></select><button class="btn light">Guardar</button></form></td><td><?=eh($r['ultimo_acceso']?:'—')?></td><td><span class="badge <?=$r['activo']?'badge-green':'badge-red'?>"><?=$r['activo']?'ACTIVO':'INACTIVO'?></span></td><td><div class="toolbar"><form method="post"><input type="hidden" name="csrf" value="<?=eh(srnu_auth_csrf())?>"><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="activo" value="<?=$r['activo']?0:1?>"><button class="btn light"><?=$r['activo']?'Desactivar':'Activar'?></button></form><form method="post" class="toolbar" onsubmit="return confirm('¿Cambiar la contraseña de este usuario?')"><input type="hidden" name="csrf" value="<?=eh(srnu_auth_csrf())?>"><input type="hidden" name="accion" value="password"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="password" name="password" minlength="10" required placeholder="Nueva contraseña"><button class="btn light">Cambiar</button></form></div></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
